function energyUnits(c){const d=D(c)||{},name=enName(c)+' '+c.name;if(d.energyType!=='Special')return [energyType(c)];if(/Double Colorless|더블 무색/i.test(name))return ['Colorless','Colorless'];if(/Rainbow Energy|레인보우 에너지/i.test(name))return ['*'];return ['Colorless'];}
function poolOf(slot){return slot.energy.flatMap(energyUnits);}
function missingCost(slot,cost){const pool=poolOf(slot);let missing=0,colorless=0;(cost||[]).forEach(type=>{if(type==='Colorless'){colorless++;return;}let i=pool.indexOf(type);if(i<0)i=pool.indexOf('*');if(i<0)missing++;else pool.splice(i,1);});return missing+Math.max(0,colorless-pool.length);}
