 consume(/Discard all Energy from this Pokémon\.?/i,()=>r.discard=99);
 consume(/Discard (an|\d+) (?:\{([A-Z])\} )?Energy from this Pokémon\.?/i,m=>{r.discard=m[1].toLowerCase()==='an'?1:+m[1];r.discardType=symbol[m[2]]||null;});
 consume(/Draw (\d+|a) cards?\.?/i,m=>r.draw=m[1].toLowerCase()==='a'?1:+m[1]);
 consume(/This attack also does (\d+) damage to each of your opponent's Benched Pokémon\.?(?: \(Don't apply Weakness and Resistance for Benched Pokémon\.\))?/i,m=>r.bench=+m[1]);
 consume(/(?:Your opponent's Active Pokémon|The Defending Pokémon) is now (Burned|Poisoned|Asleep|Paralyzed|Confused)\.?/i,m=>r.status={burned:'burn',poisoned:'poison',asleep:'asleep',paralyzed:'paralyzed',confused:'confused'}[m[1].toLowerCase()]);
 consume(/Flip a coin\. If tails, this attack does nothing\.?/i,()=>{if(simulate)damage*=.5;else if(rnd()>=.5){damage=0;r.self=r.heal=r.discard=r.draw=r.bench=0;r.status=null;r.notes.push('코인 뒷면 · 기술 실패');}});
 consume(/Flip a coin\. If heads, this attack does (\d+) more damage\.?/i,m=>damage+=simulate?+m[1]/2:(rnd()<.5?+m[1]:0));
 consume(/During your next turn, this Pokémon can't attack\.?/i,()=>r.block=true);
 // Unknown effect text is never silently treated as a complete automatic effect.
 r.auto=!remaining.replace(/[.\s]/g,'').length&&(!/[+×x-]/.test(String(attack.damage||''))||text!==remaining);
