P.attackInfo=attackInfo;
function attackBlocked(p){return !p.active||p.active.status.asleep||p.active.status.paralyzed||(p.active.blockUntil!=null&&p.active.blockUntil>=(p.turns||0));}
window.bestAttack=function(slot,def){if(!active())return old.bestAttack(slot,def);let best={atk:null,dmg:0,score:-Infinity};if(!slot)return best;const owner=field(opp).includes(slot)?opp:field(me).includes(slot)?me:opp;(D(topCard(slot))?.attacks||[]).forEach(a=>{if(!canPay(slot,a.cost))return;const r=attackInfo(slot,a,def,owner,true);if(!r.auto)return;let score=r.damage+r.bench*12/10-Math.min(slot.energy.length,r.discard)*14+r.heal*.2;if(def&&r.damage>=hpOf(def)-def.dmg)score+=500+prizeCount(def)*160;if(r.self>=hpOf(slot)-slot.dmg)score-=250;if(r.block)score-=35;if(aiLv<=3)score+=rnd()*45;if(!best.atk||score>best.score)best={atk:a,dmg:r.damage,score};});return best;};
function applyStatus(slot,status){if(!slot||!status)return;if(['asleep','paralyzed','confused'].includes(status))['asleep','paralyzed','confused'].forEach(k=>slot.status[k]=false);slot.status[status]=true;}
function discardAttackEnergy(p,slot,count,type){let left=count;for(let i=slot.energy.length-1;i>=0&&left>0;i--)if(!type||energyUnits(slot.energy[i]).includes(type)){p.discard.push(slot.energy.splice(i,1)[0]);left--;}}
async function executeAttack(who,attack,manual){const p=who==='me'?me:opp,enemy=who==='me'?opp:me,slot=p.active;if(!slot||!enemy.active||p.attacked||ended)return false;if(!canPay(slot,attack.cost)||attackBlocked(p)||turnNo===1&&p.first)return false;
 if(who==='me'&&!canPlay())return false;p.attacked=true;P.phase=who==='me'?'resolving':'ai';closeSheet();
 if(slot.status.confused&&rnd()>=.5){slot.dmg+=30;log(p.nick+' 혼란 · 자신에게 30');await settleKO();if(!ended){P.phase=who==='me'?'player':'ai';await finishTurn(who);}return true;}
 const r=manual||attackInfo(slot,attack,enemy.active,p,false);if(!r.auto&&!manual){p.attacked=false;P.phase=who==='me'?'player':'ai';return false;}
 if(manual&&manual.hits)manual.hits.forEach(h=>{const target=h.target<0?enemy.active:enemy.bench[h.target];if(target)target.dmg+=h.dmg;});else{enemy.active.dmg+=r.damage;enemy.bench.forEach(s=>s.dmg+=r.bench||0);}
 slot.dmg=Math.max(0,slot.dmg+(r.self||0)-(r.heal||0));discardAttackEnergy(p,slot,r.discard||0,r.discardType);p.hand.push(...p.deck.splice(0,r.draw||0));applyStatus(enemy.active,r.status);if(r.block)slot.blockUntil=p.turns+1;
 log(p.nick+' · '+topCard(slot).name+'의 '+attack.name+' → '+(manual?'수동 효과 처리':r.damage+' 데미지')+(r.notes?.length?' · '+r.notes.join(', '):''));fxHit(who==='me'?'o':'m',-1);sync();await settleKO();if(!ended){P.phase=who==='me'?'player':'ai';await finishTurn(who);}return true;}
const oldAttack=$('btnAttack').onclick;
$('btnAttack').onclick=e=>{if(!active())return oldAttack(e);e.preventDefault();if(!canPlay())return;if(!me.active||!opp.active)return;if(turnNo===1&&me.first){toast('선공 첫 턴은 공격할 수 없어요');return;}if(attackBlocked(me)){toast('상태이상 또는 이전 기술 효과로 공격할 수 없어요');return;}
 const attacks=D(topCard(me.active))?.attacks||[];sheet('<h3>'+esc(topCard(me.active).name)+' · 기술 선택</h3><p class="battle-note">에너지가 맞는 기술을 선택하면 공격하고 턴이 자동으로 끝납니다.</p>'+attacks.map((a,i)=>{const r=attackInfo(me.active,a,opp.active,me,true),pay=canPay(me.active,a.cost);return '<button type="button" class="atkrow" data-attack="'+i+'" '+(!pay?'disabled':'')+'><b>'+esc(a.name)+' · '+(a.cost||[]).map(KO).join(' ')+'</b><small>'+(pay?(r.auto?'예상 '+r.damage+' 데미지 (약점·저항 반영)':'카드 효과를 직접 확인하고 처리'):'에너지 '+missingCost(me.active,a.cost)+'개 부족')+'</small><span class="tag">'+(r.auto?'자동 처리':'수동 효과')+'</span></button>';}).join('')+'<button type="button" class="ghost" style="width:100%" onclick="closeSheet()">취소</button>');document.querySelectorAll('[data-attack]').forEach(b=>b.onclick=()=>{const a=attacks[+b.dataset.attack];const r=attackInfo(me.active,a,opp.active,me,true);if(r.auto)executeAttack('me',a);else manualAttack(a);});};
function manualAttack(attack){const targets=[opp.active].concat(opp.bench),attacker=me.active,openedTurn=turnNo;sheet('<h3>'+esc(attack.name)+' · 수동 효과</h3><p class="battle-note manual">이 기술의 효과는 자동 해석하지 못했어요. 아래에 최종 데미지를 입력하고, 에너지 트래시 등 추가 효과는 [효과 직접 처리]에서 먼저 처리하세요.</p><p>'+esc(attack.effect||'')+'</p>'+targets.map((s,i)=>'<label class="row">'+esc(topCard(s).name)+'<input type="number" min="0" step="10" data-manual-hit="'+(i-1)+'" value="'+(i===0?parseDmg(attack.damage):0)+'" style="max-width:90px"></label>').join('')+'<button type="button" class="primary-wide" id="manualAttackGo">입력한 효과 적용 · 턴 종료</button><button type="button" class="ghost" style="width:100%;margin-top:8px" onclick="closeSheet()">취소</button>');$('manualAttackGo').onclick=()=>{if(!canPlay()||me.active!==attacker||turnNo!==openedTurn||targets.some((s,i)=>s!==[opp.active].concat(opp.bench)[i]))return;const hits=Array.from(document.querySelectorAll('[data-manual-hit]')).map(el=>({target:+el.dataset.manualHit,dmg:Math.max(0,Math.min(9990,Math.round((+el.value||0)/10)*10))}));executeAttack('me',attack,{auto:true,hits});};}
