function kindOf(c){const n=(enName(c)+' '+c.name).toLowerCase();if(isBossCard(c))return 'boss';if(/professor.*research|박사의 연구/.test(n))return 'research';if(/youngster|반바지 꼬마/.test(n))return 'youngster';if(/iono|모야모/.test(n))return 'iono';if(/judge|심판/.test(n))return 'judge';if(/nemona|네모/.test(n))return 'draw3';if(/nest ball|네스트볼/.test(n))return 'nest';if(/ultra ball|하이퍼볼/.test(n))return 'ultra';if(/^switch | switch$|포켓몬 교체/.test(n))return 'switch';if(/rare candy|이상한사탕/.test(n))return 'candy';return 'manual';}
function supportAllowed(p){return !p.supporterUsed&&!(turnNo===1&&p.first);}
function spendTrainer(p,c){const i=p.hand.indexOf(c);if(i<0)return false;const d=D(c)||{};if(d.trainerType==='Supporter'&&!supportAllowed(p))return false;p.hand.splice(i,1);p.discard.push(c);if(d.trainerType==='Supporter')p.supporterUsed=true;log(p.nick+' · '+c.name+' 사용');return true;}
function drawEffect(p,n){p.hand.push(...p.deck.splice(0,Math.max(0,n)));}
function resolveDrawSupporter(p,enemy,kind){if(kind==='research'){p.discard.push(...p.hand);p.hand=[];drawEffect(p,7);}if(kind==='youngster'){p.deck=shuffle(p.deck.concat(p.hand));p.hand=[];drawEffect(p,5);}if(kind==='draw3')drawEffect(p,3);
 if(kind==='judge'){[p,enemy].forEach(x=>{x.deck=shuffle(x.deck.concat(x.hand));x.hand=[];drawEffect(x,4);});}if(kind==='iono'){[p,enemy].forEach(x=>{x.deck.push(...shuffle(x.hand));x.hand=[];drawEffect(x,x.prizes.length);});}}
window.playTrainer=function(i,supporter){if(!active())return old.playTrainer(i,supporter);if(!canAct())return;const c=me.hand[i];if(!c)return;const d=D(c)||{};if(d.trainerType==='Supporter'&&!supportAllowed(me)){toast('이번 턴에는 서포트를 사용할 수 없어요');return;}const kind=kindOf(c);const valid=()=>canPlay()&&me.hand.includes(c);
 if(kind==='boss')return old.playTrainer(i,true);
 if(['research','youngster','draw3','judge','iono'].includes(kind)){if(spendTrainer(me,c)){resolveDrawSupporter(me,opp,kind);closeSheet();sync();}return;}
 if(kind==='switch'){if(!me.active||!me.bench.length){toast('교체할 벤치가 없어요');return;}selectCards('교체할 포켓몬',me.bench.map(topCard),cards=>{const j=me.bench.findIndex(s=>topCard(s).uid===cards[0].uid);if(!valid()||j<0)return;if(spendTrainer(me,c)){switchBench(me,cards[0].uid,topCard(me.active).uid);closeSheet();sync();}});return;}
 if(kind==='nest'||kind==='ultra'){if(kind==='nest'&&me.bench.length>=5){toast('벤치가 가득 찼어요');return;}const pool=me.deck.filter(x=>D(x)?.category==='Pokemon'&&(kind!=='nest'||isBasic(x)));if(!pool.length){toast('덱에 가져올 포켓몬이 없어요');return;}const pickTarget=costs=>selectCards(kind==='nest'?'벤치에 낼 기본 포켓몬':'손패로 가져올 포켓몬',pool,cards=>{const chosen=cards[0];if(!valid()||!me.deck.includes(chosen)||costs.some(x=>!me.hand.includes(x)))return;if(!spendTrainer(me,c))return;costs.forEach(x=>{me.hand.splice(me.hand.indexOf(x),1);me.discard.push(x);});me.deck.splice(me.deck.indexOf(chosen),1);if(kind==='nest')me.bench.push(slotOf(chosen));else me.hand.push(chosen);shuffle(me.deck);log(chosen.name+(kind==='nest'?' 벤치로':' 손패로'));closeSheet();sync();});
  if(kind==='ultra'){if(me.hand.length<3){toast('하이퍼볼 외에 버릴 카드 2장이 필요해요');return;}selectCards('먼저 버릴 손패 2장',me.hand.filter(x=>x!==c),pickTarget,{count:2,note:'포켓몬 선택까지 마치면 비용과 효과를 함께 처리합니다.'});}else pickTarget([]);return;}
 sheet('<h3>'+esc(c.name)+' · 수동 효과</h3><p class="battle-note manual">이 카드 효과는 자동 처리되지 않습니다. 내용을 확인한 뒤 사용해 주세요.</p><p>'+esc(d.effect||'카드 설명을 확인해 주세요.')+'</p><button type="button" class="primary-wide" id="manualTrainer">카드 사용 · 효과 직접 처리</button><button type="button" class="ghost" style="width:100%;margin-top:8px" onclick="closeSheet()">취소</button>');$('manualTrainer').onclick=()=>{if(valid()&&spendTrainer(me,c)){sync();effectMenu();}};
};
function effectMenu(){if(!canAct())return;sheet('<h3>카드 효과 직접 처리</h3><p class="battle-note manual">방금 사용한 카드에 적힌 범위만 처리하세요.</p><div class="acts"><button class="soft" onclick="drawN(1)">1장 드로</button><button class="soft" onclick="searchDeck()">덱 검색</button><button class="soft" onclick="document.getElementById(\'btnBatchDiscard\').onclick()">손패 트래시</button><button class="soft" onclick="gustMenu()">상대 벤치 호출</button><button class="ghost" onclick="document.getElementById(\'btnCoin\').onclick({preventDefault:function(){}})">코인</button><button class="ghost" onclick="closeSheet()">처리 완료</button></div>');}
window.toActive=function(i){if(!active())return old.toActive(i);if(P.phase!=='setup'||me.active||P.paused)return;const c=me.hand[i];if(!c||!isBasic(c))return;me.hand.splice(i,1);me.active=slotOf(c);closeSheet();sync();};
window.toBench=function(i){if(!active())return old.toBench(i);if((P.phase!=='setup'&&!canPlay())||P.paused)return;const c=me.hand[i];if(!c||!isBasic(c)||me.bench.length>=5){toast('기본 포켓몬만 벤치 5마리까지 낼 수 있어요');return;}me.hand.splice(i,1);me.bench.push(slotOf(c));closeSheet();sync();};
window.attach=function(i,kind,from){if(!active())return old.attach(i,kind,from);if(!canAct())return;const c=me.hand[i],d=D(c)||{};if(!c)return;if(kind==='energy'&&me.energyUsed){toast('에너지는 한 턴에 1장 붙일 수 있어요');return;}let targets=field(me);if(kind==='evolve')targets=targets.filter(s=>turnNo>2&&s.turnPlayed!==turnNo&&s.turnEvolved!==turnNo&&String(topCard(s).name).toLowerCase()===String(d.evolveFrom).toLowerCase());if(kind==='tool')targets=targets.filter(s=>!s.tools.length);if(!targets.length){toast('지금 붙일 수 있는 포켓몬이 없어요');return;}
 selectCards(kind==='evolve'?'진화할 포켓몬':'카드를 붙일 포켓몬',targets.map(topCard),cards=>{if(!canPlay()||!me.hand.includes(c))return;const target=targets.find(s=>topCard(s).uid===cards[0].uid);if(!target||!field(me).includes(target))return;me.hand.splice(me.hand.indexOf(c),1);if(kind==='energy'){target.energy.push(c);me.energyUsed=true;}else if(kind==='tool')target.tools.push(c);else{target.stack.push(c);target.turnEvolved=turnNo;target.status={};delete target.blockUntil;}log(c.name+' → '+topCard(target).name);closeSheet();sync();});};
const originalSwitch=switchBench;window.switchBench=function(p,target,previous){const prior=p?.active;const ok=originalSwitch(p,target,previous);if(ok&&prior)delete prior.blockUntil;return ok;};
function payRetreat(p,s){const cost=Number(D(topCard(s))?.retreat??2);if(poolOf(s).length<cost)return false;let paid=0;while(paid<cost&&s.energy.length){const c=s.energy.pop();paid+=energyUnits(c).length;p.discard.push(c);}p.retreated=true;return true;}
window.retreat=function(){if(!active())return old.retreat();if(!canAct()||!me.active)return;if(me.retreated||me.active.status.asleep||me.active.status.paralyzed){toast('이번 턴에는 후퇴할 수 없어요');return;}const cost=Number(D(topCard(me.active))?.retreat??2);if(poolOf(me.active).length<cost){toast('후퇴 에너지가 '+cost+'개 필요해요');return;}const prior=me.active;selectCards('후퇴 후 배틀로 나올 포켓몬',me.bench.map(topCard),cards=>{if(!canPlay()||me.active!==prior)return;if(!me.bench.some(s=>topCard(s).uid===cards[0].uid))return;if(payRetreat(me,prior)){switchBench(me,cards[0].uid,topCard(prior).uid);closeSheet();sync();}},{note:'후퇴 비용 '+cost+'개를 트래시합니다. 후퇴는 한 턴에 1번입니다.'});};
window.promote=function(i){if(!active())return old.promote(i);if(P.phase==='promotion'){if(!me.bench[i])return;const c=topCard(me.bench[i]);const b=Array.from(document.querySelectorAll('[data-choice]')).find(el=>+el.dataset.choice===i);if(b)b.click();return;}if(me.active)return retreat();};
window.ko=function(i){if(!active())return old.ko(i);if(!canAct())return;const s=getSlot(i);if(!s)return;if(s.dmg<hpOf(s)){toast('남은 HP가 있어요. 효과로 기절했다면 데미지부터 조정해 주세요');return;}settleKO();};
window.prizeMenu=function(){if(!active())return old.prizeMenu();sheet('<h3>프라이즈 '+me.prizes.length+'장 남음</h3><p class="battle-note">AI전에서는 상대 포켓몬이 기절하면 프라이즈를 자동으로 가져옵니다.</p><button class="primary-wide" onclick="closeSheet()">확인</button>');};
window.drawN=function(n){if(!active())return old.drawN(n);if(!canAct())return;const count=Math.max(0,Math.min(60,Math.floor(Number(n)||0)));if(!count)return;const got=Math.min(count,me.deck.length);drawEffect(me,got);log('카드 효과 · '+got+'장 드로');sync();};
const oldDraw=$('btnDraw').onclick;$('btnDraw').onclick=e=>{if(!active())return oldDraw(e);toast('AI전의 턴 시작 드로는 자동이에요');};
window.handMenu=function(i){if(!active())return old.handMenu(i);if(P.phase==='promotion'){choosePromotion();return;}if(P.phase==='setup'||canPlay()){old.handMenu(i);const c=me.hand[i],b=$('sheetIn').querySelector('.preview button');if(c&&b)b.onclick=()=>cardDetail(c.id,c.name);return;}const c=me.hand[i];if(c)cardDetail(c.id,c.name);};
window.renderHandActs=function(i,c,d){if(!active())return old.renderHandActs(i,c,d);if(me.hand[i]!==c||!$('hmActs'))return;if(P.phase==='setup'){let h='';if(isBasic(c)){if(!me.active)h+='<button class="full" onclick="toActive('+i+')">첫 배틀 포켓몬으로</button>';if(me.bench.length<5)h+='<button class="soft full" onclick="toBench('+i+')">벤치에 내기</button>';}h+='<button class="ghost full" onclick="closeSheet()">닫기</button>';$('hmActs').innerHTML=h;return;}old.renderHandActs(i,c,d);if(d?.category==='Trainer'&&kindOf(c)==='manual')$('hmActs').insertAdjacentHTML('afterbegin','<p class="battle-note manual full">이 카드의 효과는 수동 처리합니다.</p>');};
