function aiDrawSupporter(){if(!supportAllowed(opp))return;if(aiLv>=5&&opp.hand.some(isBossCard)&&aiBossTarget(true))return;const options=opp.hand.filter(c=>D(c)?.trainerType==='Supporter').map(c=>{const kind=kindOf(c);let score=0;if(kind==='research')score=(7-(opp.hand.length-1))*12;if(kind==='youngster')score=(5-(opp.hand.length-1))*12;if(kind==='draw3')score=30;if(kind==='judge')score=(4-(opp.hand.length-1))*8+(me.hand.length-4)*5;if(kind==='iono')score=(opp.prizes.length-(opp.hand.length-1))*8+(me.hand.length-me.prizes.length)*5;return {c,kind,score};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);if(options[0]&&spendTrainer(opp,options[0].c))resolveDrawSupporter(opp,me,options[0].kind);}
function aiItems(){const items=opp.hand.filter(c=>D(c)?.category==='Trainer'&&D(c)?.trainerType!=='Supporter');for(const c of items){if(!opp.hand.includes(c))continue;const kind=kindOf(c);
 if(kind==='nest'&&opp.bench.length<5){const pool=opp.deck.filter(isBasic).sort((a,b)=>aiBasicValue(b)-aiBasicValue(a));const chosen=aiLv<=2?pool[Math.floor(rnd()*pool.length)]:pool[0];if(chosen&&spendTrainer(opp,c)){opp.deck.splice(opp.deck.indexOf(chosen),1);opp.bench.push(slotOf(chosen));shuffle(opp.deck);log(chosen.name+' 벤치로');}}
 if(kind==='ultra'&&opp.hand.length>=3){const pool=opp.deck.filter(x=>D(x)?.category==='Pokemon');const evos=pool.filter(x=>field(opp).some(s=>String(D(x).evolveFrom||'').toLowerCase()===topCard(s).name.toLowerCase()));const chosen=evos[0]||(opp.bench.length<4?pool.filter(isBasic).sort((a,b)=>aiBasicValue(b)-aiBasicValue(a))[0]:null);if(!chosen)continue;const costs=opp.hand.filter(x=>x!==c).sort((a,b)=>aiCardValue(a)-aiCardValue(b)).slice(0,2);if(costs.length===2&&spendTrainer(opp,c)){costs.forEach(x=>{opp.hand.splice(opp.hand.indexOf(x),1);opp.discard.push(x);});opp.deck.splice(opp.deck.indexOf(chosen),1);opp.hand.push(chosen);shuffle(opp.deck);log(chosen.name+' 손패로');}}
 if(kind==='candy'){const stage2=opp.hand.filter(x=>D(x)?.stage==='Stage2');let applied=false;for(const evo of stage2){const target=field(opp).find(s=>aiCanCandy(s,evo));if(target&&spendTrainer(opp,c)){opp.hand.splice(opp.hand.indexOf(evo),1);target.stack.push(evo);target.status={};target.turnEvolved=turnNo;delete target.blockUntil;applied=true;break;}}if(applied)log('AI · 이상한사탕 진화');}
 }}
function aiSwitchOrRetreat(){if(!opp.active||!opp.bench.length||aiLv<4)return;const current=opp.active,currentAttack=attackBlocked(opp)?{atk:null,score:-Infinity,dmg:0}:bestAttack(current,me.active);const threat=me.active?bestAttack(me.active,current):{dmg:0};const alternatives=opp.bench.map(s=>({s,atk:bestAttack(s,me.active)})).filter(x=>x.atk.atk&&(!currentAttack.atk||x.atk.score>currentAttack.score+30||(aiLv>=7&&threat.dmg>=hpOf(current)-current.dmg&&x.atk.dmg>=currentAttack.dmg&&bestAttack(me.active,x.s).dmg<hpOf(x.s)-x.s.dmg))).sort((a,b)=>b.atk.score-a.atk.score);if(!alternatives.length)return;const target=alternatives[0].s,card=opp.hand.find(c=>kindOf(c)==='switch');if(card){if(!spendTrainer(opp,card))return;}else if(current.status.asleep||current.status.paralyzed||opp.retreated||!payRetreat(opp,current))return;switchBench(opp,topCard(target).uid,topCard(current).uid);log('AI · '+topCard(target).name+' 배틀로 교체');}
function aiAbilities(){if(aiLv<4)return;field(opp).forEach(s=>{if(s.abilityUsed===turnNo)return;const ab=D(topCard(s))?.abilities||[];for(const a of ab){const m=String(a.effect||'').match(/^Once during your turn, you may draw (\d+) cards?\.?$/i);if(m){drawEffect(opp,+m[1]);s.abilityUsed=turnNo;log('AI · '+a.name+' 특성');break;}}});}
async function runAI(){if(!active()||ended||turn!=='opp'||P.running)return;P.running=true;const epoch=P.epoch;P.phase='ai';const steps=[['필드와 진화 준비',()=>{aiDeployBasics();aiEvolve();}],['특성 확인',aiAbilities],['서포트 판단',aiDrawSupporter],['필요한 포켓몬 찾기',aiItems],['새 카드 전개',()=>{aiDeployBasics();aiEvolve();}],['공격 에너지 준비',()=>{if(opp.energyUsed)return;const plan=aiEnergyPlan();if(plan){opp.hand.splice(opp.hand.indexOf(plan.energy),1);plan.slot.energy.push(plan.energy);opp.energyUsed=true;log('AI · '+plan.energy.name+' → '+topCard(plan.slot).name);}}],['배틀 포켓몬 결정',aiSwitchOrRetreat],['보스의 지령 판단',()=>{if(aiLv<5||!supportAllowed(opp))return;const card=opp.hand.find(isBossCard),target=aiBossTarget(false);if(card&&target&&spendTrainer(opp,card)){switchBench(me,topCard(target.slot).uid,topCard(me.active).uid);log('AI · 보스의 지령 → '+topCard(me.active).name);}}]];
 try{for(const [name,fn] of steps){if(!await pausePoint(epoch))return;P.step=name;fn();sync();await delay(P.speed);if(epoch!==P.epoch||ended)return;}if(!await pausePoint(epoch))return;P.step='공격 선택';sync();const best=opp.active&&me.active?bestAttack(opp.active,me.active):{atk:null};if(best.atk&&!attackBlocked(opp)&&!(turnNo===1&&opp.first)){await executeAttack('opp',best.atk);}else{log('AI · '+(turnNo===1&&opp.first?'선공 첫 턴':attackBlocked(opp)?'상태이상으로 공격 불가':'사용 가능한 자동 기술 없음')+' · 턴 종료');await finishTurn('opp');}}
 catch(e){console.error(e);P.phase='error';P.step='AI 진행을 잠시 멈췄어요';render();sheet('<h3>진행 복구</h3><p>처리 중 오류가 발생했습니다. 현재 필드는 유지됩니다.</p><button class="primary-wide" id="recoverAI">현재 AI 턴을 종료하고 계속</button>');$('recoverAI').onclick=()=>{P.phase='ai';P.paused=false;finishTurn('opp');};}finally{P.running=false;}}
P.run=runAI;P.settleKO=settleKO;P.finishTurn=finishTurn;P.startActor=startActor;P.begin=begin;P.checkup=checkup;P.executeAttack=executeAttack;
