 const isAI=active();document.querySelector('.tools').classList.toggle('ai-tools',isAI);$('pauseAI').classList.toggle('hide',!isAI||ended);$('pauseAI').textContent=P.paused?'계속하기':'일시정지';$('btnReady').classList.toggle('hide',!isAI||P.phase!=='setup');$('btnReady').disabled=!me.active||P.paused;$('btnSwap').classList.toggle('hide',!solo||ai);
